method_definition:
private Arg createArg(String key, int position) {
        Arg arg = createArg(key);
        arg.setPosition(position);
        return arg; 
    }

docstring:
/**
     * Convenience Method - create argument (name specified, no position)
     */

method_definition:
private Arg createArg(String key, String name) {
        Arg arg = createArg(key);
        arg.setName(name);
        return arg; 
    }

