                "1365201X",
                };
        invalid = new String[] {
                "03178472", // wrong check
                "1050-124X", // format char
                " 1365201X",
                "1365201X ",
                " 1365201X ",
        };
        missingMessage = "Code is missing";
        zeroSum = "00000000";
    }

